custom_css:
/* 添加你提供的代码 */
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    background-image: none;
}

/* 定义颜色变量 */
* {
    --black30a: rgba(255, 255, 255, 0.3);
    --black50a: rgba(255, 255, 255, 0.5);
    --white30a: rgba(0, 0, 0, 0.4);
    --white50a: rgba(0, 0, 0, 0.5);
}

/* 顶部设置 */
#top-settings-holder {
    color: #000000; /* 黑色 */
}

.drawer-icon.closedIcon {
    opacity: 0.6 !important; /* 强制完全不透明 */
}

/* 输入框 */
#send_textarea {
    color: #000000; /* 黑色 */
}

/* 滚动条 - 黑色 & 微信灰色 */
* {
    scrollbar-color: #000000 #EDEDED; /* 黑色和微信灰色 */
    scrollbar-width: thin;
}

/* 格式化文本 */
.formatted-text {
    color: #000000; /* 黑色 */
}

/* 代码块 */
/* 小代码块 */
code {
    background-color: rgba(237, 237, 237, 0.5); /* 微信灰色背景 */
    color: #000000; /* 黑色文字 */
    border: none; /* 不要边框 */
}

/* 禁用 .hljs 的背景颜色和文字颜色 */
.hljs {
    background-color: transparent !important;
    color: inherit !important;
}

/* 大代码块 */
pre {
    font-family: monospace;
    background-color: rgba(237, 237, 237, 0.3); /* 微信灰色背景 */
    color: #000000; /* 黑色文字 */
    padding: 10px;
    border-radius: 5px; /* 边角弧度改为5px */
    border: none; /* 不要边框 */
    background-clip: padding-box;
    position: relative;
}

/* 按钮和文本框 */
.menu_button, .text_pole, textarea {
    background-color: rgba(237, 237, 237, 0.5); /* 微信灰色 */
    color: #000000; /* 黑色 */
    border: 1px solid #000000; /* 边框为黑色 */
}

/* 编辑框黑色去除 */
.edit_textarea {
    background-color: transparent !重要;
}

/* 消息气泡 */
body.bubblechat .mes {
    background-color: unset !important;
}

/* char消息块 */
body.bubblechat .mes_block {
    background-color: transparent; /* 设置气泡为透明 */
    padding: 10px;
    border-radius: 5px; /* 将边角弧度改为5px */
    width: max-content;
    position: relative; /* 为伪元素定位做准备 */
    max-width: 75%; /* 气泡最大宽度为聊天框的 75% */
    border: none; /* 不要边框 */
}

/* 用户消息块 */
body.bubblechat .mes[is_user="true"] .mes_block {
    background-color: transparent; /* 设置气泡为透明 */
    order: -1;
    margin-left: auto;
    border-radius: 5px; /* 将边角弧度改为5px */
    position: relative; /* 为伪元素定位做准备 */
    padding-right: 20px; /* 为右侧的 10px 空间和内容留出额外的 padding */
    padding-left: 10px; /* 为左侧留出 padding 以与矩形对齐 */
    max-width: 75%; /* 气泡最大宽度为聊天框的 75% */
    border: none; /* 不要边框 */
}

/* 叠加一个绿色圆角矩形 - 用户消息 */
body.bubblechat .mes[is_user="true"] .mes_block::before {
    content: ""; /* 不显示文字 */
    position: absolute;
    top: 0;
    right: 10px; /* 距离气泡右侧边界10px */
    bottom: 0;
    left: 0; /* 左端与气泡左边界对齐 */
    background-color: #9EEA6A; /* 微信绿色 */
    border-radius: 5px; /* 保持圆角 */
    z-index: -1; /* 将矩形放在文本后面 */
}

/* 用户气泡右上角的三角形 */
body.bubblechat .mes[is_user="true"] .mes_block::after {
    content: ""; /* 空内容表示三角形 */
    position: absolute;
    top: 20px; /* 与气泡顶部距离为20px */
    right: 5px; /* 距离透明气泡的内沿为5px */
    width: 0;
    height: 0;
    border-left: 5px solid #9EEA6A; /* 三角形的颜色与绿色区域相同 */
    border-top: 5px solid transparent;
    border-bottom: 5px solid transparent;
}

/* 叠加一个白色圆角矩形 - char消息 */
body.bubblechat .mes:not([is_user="true"]) .mes_block::before {
    content: ""; /* 不显示文字 */
    position: absolute;
    top: 0;
    left: 10px; /* 距离气泡左侧边界10px */
    bottom: 0;
    right: 0; /* 右端与气泡右边界对齐 */
    background-color: #FFFFFF; /* 纯白色 */
    border-radius: 5px; /* 保持圆角 */
    z-index: -1; /* 将矩形放在文本后面 */
}

/* char气泡左上角的三角形 */
body.bubblechat .mes:not([is_user="true"]) .mes_block::after {
    content: ""; /* 空内容表示三角形 */
    position: absolute;
    top: 20px; /* 与气泡顶部距离为20px */
    left: 5px; /* 距离透明气泡的内沿为5px */
    width: 0;
    height: 0;
    border-right: 5px solid #FFFFFF; /* 三角形的颜色与白色区域相同 */
    border-top: 5px solid transparent;
    border-bottom: 5px solid transparent;
}

/* char消息块 - 调整文本对齐 */
body.bubblechat .mes:not([is_user="true"]) .mes_block {
    padding-left: 20px; /* 为左侧的 10px 空间和内容留出额外的 padding */
    padding-right: 10px; /* 为右侧留出 padding 以与矩形对齐 */
    max-width: 75%; /* 气泡最大宽度为聊天框的 75% */
    border: none; /* 不要边框 */
}

/* 消息发送者名称 */
.mes_block .ch_name {
    font-size: 0.9em;
    color: #000000; /* 黑色 */
}

/* QR设置隐藏 */
#send_form:hover #qr--bar {
    height: 40px;
    transition: all 0.5s ease;
}

#qr--bar {
    height: 0.1px;
}

/* 隐藏代理警告 */
#ReverseProxyWarningMessage { display: none !important; }

/* 标注区域 */
.mes_text blockquote {
    background-color: rgba(237, 237, 237, 0.3); /* 微信灰色 */
    border-left: 5px solid #000000; /* 黑色边框 */
    color: #000000; /* 黑色文字 */
}

/* 消息发送者名称 - 鼠标悬停显示 */
.mes_block .ch_name {
    height: 0.1px; /* 平时隐藏 */
    overflow: hidden;
    transition: all 0.5s ease;
}

.mes_block:hover .ch_name {
    height: 55px; /* 鼠标悬停时显示 */
}

/* 删除按钮 */
#delete_button, .redWarningBG, .menu_button.popup-button-ok {
    background: linear-gradient(to bottom, rgba(255, 204, 229, 0.8), rgba(255, 160, 177, 0.8)) !important;
}

.neo-range-input {
    background-color: rgba(237, 237, 237, 0.6); /* 微信灰色背景 */
    border: 1px solid #000000; /* 黑色边框 */
    color: #000000; /* 黑色文字 */
}

.range-block-counter input {
    background-color: rgba(237, 237, 237, 0.6); /* 微信灰色 */
    color: #000000; /* 黑色文字 */
    border: 1px solid #000000; /* 黑色边框 */
}

select {
    background-color: rgba(237, 237, 237, 0.6); /* 微信灰色 */
    color: #000000; /* 黑色文字 */
    border: 1px solid #000000; /* 黑色边框 */
}

/* 气泡只包裹正文，名称、头像和操作区不再进入气泡背景。 */
/* 覆盖旧版 `.mes_block` 气泡：名称和正文同属此容器，不能在这里绘制背景。 */
body.bubblechat .mes:not([is_user="true"]) .mes_block,
body.bubblechat .mes[is_user="true"] .mes_block {
    width: auto;
    max-width: none;
    margin-left: 0;
    padding: 0;
    border-radius: 0;
}

body.bubblechat .mes:not([is_user="true"]) .mes_block::before,
body.bubblechat .mes:not([is_user="true"]) .mes_block::after,
body.bubblechat .mes[is_user="true"] .mes_block::before,
body.bubblechat .mes[is_user="true"] .mes_block::after {
    content: none !important;
    display: none !important;
}

body.bubblechat .mes .mes_text {
    position: relative;
    z-index: 0;
    display: flow-root;
    width: fit-content;
    max-width: 100%;
    margin-top: 4px;
    padding: 10px 14px;
    border-radius: 5px;
    background-color: #FFFFFF;
    color: #000000;
}

body.bubblechat .mes .mes_text::before {
    content: "";
    position: absolute;
    top: 16px;
    left: -5px;
    width: 0;
    height: 0;
    border-top: 5px solid transparent;
    border-bottom: 5px solid transparent;
    border-right: 5px solid #FFFFFF;
}

body.bubblechat .mes[is_user="true"] .mes_text {
    margin-left: auto;
    background-color: #9EEA6A;
}

body.bubblechat .mes[is_user="true"] .mes_text::before {
    right: -5px;
    left: auto;
    border-right: 0;
    border-left: 5px solid #9EEA6A;
}

table {
    color: #000000; /* 黑色文字 */
}
